+#[test]
+fn duplicate_names_stay_broad_until_a_file_disambiguates_them() {
+    // Different bodies keep the existing identical-content deduplication from
+    // removing one file before symbol expansion gets to see it.
+    let other = A.replace("return 1", "return 10");
+    let f = Fixture::new(&[("left/a.py", A), ("right/a.py", &other)]);
+    let left = f.note(
+        "Quokka ledger",
+        "Keep the quokka ledger frozen.",
+        json!([{"path":"left/a.py","qualified_name":"alpha"}]),
+    );
+    let right = f.note(
+        "Wombat archive",
+        "Preserve the wombat archive.",
+        json!([{"path":"right/a.py","qualified_name":"alpha"}]),
+    );
+    let ambiguous = f.context(
+        "Which constraints apply to `alpha`?",
+        json!({"symbol_links":true}),
+    );
+    assert_eq!(
+        ambiguous["symbol_links"]["query_symbol_scope"]["applied"],
+        false
+    );
+    assert!(
+        includes(&ambiguous, &left) && includes(&ambiguous, &right),
+        "{ambiguous:#}"
+    );
+    let exact = f.context(
+        "Which constraints apply to `alpha` in left/a.py?",
+        json!({"symbol_links":true}),
+    );
+    assert_eq!(exact["symbol_links"]["query_symbol_scope"]["applied"], true);
+    assert!(
+        includes(&exact, &left) && !includes(&exact, &right),
+        "{exact:#}"
+    );
+}
